import pandas as pd, numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def load(sym): return pd.read_csv(f'../persistent/stock_data/{sym}.csv',parse_dates=['date']).set_index('date')['close']
dxy=pd.read_csv('../persistent/index_data/DXY.csv',parse_dates=['date']).set_index('date')['close']
px=pd.concat([load(s).rename(s) for s in U]+[dxy.rename('DXY')],axis=1).sort_index(); r=px.pct_change(); f=-r[U].rolling(60,min_periods=45).cov(r.DXY).div(r.DXY.rolling(60,min_periods=45).var(),axis=0)
def evalh(h):
