 q=evalh(h);print(h,'IC %.6f ICIR %.6f n %d'%(q.ic.mean(),q.ic.mean()/q.ic.std(),len(q)))
for y in [(2020,2022),(2023,2024),(2025,2026)]:
 q=a[(a.index.year>=y[0])&(a.index.year<=y[1])].ic;print(y,'mean',q.mean(),'icir',q.mean()/q.std(),'n',len(q))
